from html5lib import parseFragment
from html5lib import treewalkers
from html5lib import serializer
from urllib.parse import urlparse

ALLOWED_TAGS = frozenset({
    'a', 'abbr', 'acronym', 'b', 'blockquote', 'code',
    'em', 'i', 'li', 'ol', 'strong', 'ul',
})

ALLOWED_ATTRIBUTES = {
    'a': ['href', 'title'],
    'abbr': ['title'],
    'acronym': ['title'],
}

ALLOWED_PROTOCOLS = frozenset({'http', 'https', 'mailto'})

ALLOWED_STYLES = []


class Cleaner:
    """An HTML sanitizer that cleans HTML fragments.

    Example usage::

        from bleach.sanitizer import Cleaner

        cleaner = Cleaner()
        cleaned = cleaner.clean(html_text)

    """

    def __init__(self, tags=None, attributes=None, protocols=None,
                 strip=False, strip_comments=True, filters=None,
                 css_sanitizer=None):
        self.tags = tags if tags is not None else ALLOWED_TAGS
        self.attributes = attributes if attributes is not None else ALLOWED_ATTRIBUTES
        self.protocols = protocols if protocols is not None else ALLOWED_PROTOCOLS
        self.strip = strip
        self.strip_comments = strip_comments
        self.filters = filters if filters is not None else []
        self.css_sanitizer = css_sanitizer

    def clean(self, text):
        """Clean the given HTML fragment and return the result.

        Args:
            text: An HTML fragment to clean.

        Returns:
            A str containing the cleaned HTML fragment.
        """
        # Parse the HTML fragment into a tree
        tree = parseFragment(text)

        # Walk the tree to get tokens
        walker = treewalkers.getTreeWalker('etree')
        tokens = list(walker(tree))

        # Filter tokens
        filtered_tokens = self._filter_tokens(tokens)

        # Apply any extra filters (post-processing)
        for f in self.filters:
            filtered_tokens = list(f(filtered_tokens))

        # Serialize back to HTML
        ser = serializer.HTMLSerializer(omit_optional_tags=False)
        return ''.join(ser.serialize(filtered_tokens))

    def _filter_tokens(self, tokens):
        """Filter tokens based on the tag/attribute/protocol whitelist."""
        for token in tokens:
            token_type = token['type']

            if token_type == 'StartTag':
                yield from self._handle_start_tag(token)
            elif token_type == 'EndTag':
                yield from self._handle_end_tag(token)
            elif token_type == 'Comment':
                if not self.strip_comments:
                    yield token
            else:
                # Characters, SpaceCharacters, etc.
                yield token

    def _handle_start_tag(self, token):
        """Handle a StartTag token."""
        tag_name = token['name']

        if tag_name in self.tags:
            # Allowed tag: filter attributes
            allowed_attrs = self.attributes.get(tag_name, [])
            if '*' in self.attributes:
                allowed_attrs = allowed_attrs + self.attributes['*']

            filtered_data = {}
            for attr_name, attr_value in token['data'].items():
                if attr_name in allowed_attrs:
                    # Check protocol if this is a URL attribute
                    if self._is_url_attribute(attr_name) and attr_value:
                        if not self._allowed_protocol(attr_value):
                            continue
                    # Sanitize CSS if needed
                    if attr_name == 'style' and self.css_sanitizer:
                        attr_value = self.css_sanitizer.sanitize_css(attr_value)
                    filtered_data[attr_name] = attr_value

            token['data'] = filtered_data
            yield token
        else:
            # Disallowed tag
            if self.strip:
                # Strip the tag but keep its contents
                return  # Don't yield start or end tag
            else:
                # Escape the tag
                escaped = '&lt;%s&gt;' % tag_name
                yield {'type': 'Characters', 'data': escaped}

    def _handle_end_tag(self, token):
        """Handle an EndTag token."""
        tag_name = token['name']

        if tag_name in self.tags:
            yield token
        else:
            if self.strip:
                return
            else:
                escaped = '&lt;/%s&gt;' % tag_name
                yield {'type': 'Characters', 'data': escaped}

    def _is_url_attribute(self, attr_name):
        """Check if the attribute is a URL-bearing attribute."""
        return attr_name in {'href', 'src', 'action', 'cite', 'data',
                             'formaction', 'manifest', 'poster', 'profile'}

    def _allowed_protocol(self, value):
        """Check if the URL value has an allowed protocol."""
        # Separate by whitespace to handle multiple URLs
        for url in value.split():
            if ':' in url:
                parsed = urlparse(url)
                if parsed.scheme:
                    if parsed.scheme not in self.protocols:
                        return False
        return True

